
function complete(){window.ReactNativeWebView?.postMessage('artist-house-splash-complete');window.parent?.postMessage('artist-house-splash-complete','*');}
window.addEventListener('artist-house-splash-complete',complete,{once:true});

const crafts=[{"src":"data:image/png;base64,","ratio":1.4516129032258065},{"src":"data:image/png;base64,","ratio":1.0317460317460319},{"src":"data:image/png;base64,","ratio":0.975975975975976},{"src":"data:image/png;base64,","ratio":1.2411347517730495},{"src":"data:image/png;base64,","ratio":0.7849162011173184}], NS='http://www.w3.org/2000/svg';
crafts.reverse();
const nodes=crafts.map((asset)=>{const im=document.createElementNS(NS,'image');im.setAttribute('href',asset.src);im.setAttribute('opacity','0');document.getElementById('crafts').appendChild(im);return im;});
const logo=document.getElementById('logo'),door=document.getElementById('door'),name=document.getElementById('name'),halo=document.getElementById('halo');
const clamp=x=>Math.max(0,Math.min(1,x)),ease=x=>{x=clamp(x);return x*x*(3-2*x)};
let start=0,request=0;
function render(t){
 const shift=ease((t-.60)/.50),cx=360+(130-360)*shift,cy=560,width=235+(100-235)*shift,appear=ease((t-.08)/.48),actual=width*(.94+.06*appear);
 logo.setAttribute('transform',`translate(${cx-actual/2},${cy-actual*338/431/2}) scale(${actual/431})`);logo.setAttribute('opacity',appear);halo.setAttribute('opacity',0);
 for(let j=0;j<3;j++){document.getElementById('r'+j).setAttribute('y',0);document.getElementById('r'+j).setAttribute('height',338);}
 let close=1-ease((t-1.55)/.40);const op=[[218,194],[268,173],[268,337],[218,309]],cl=[[164,114],[268,173],[268,337],[164,337]];
 door.setAttribute('points',op.map((p,j)=>`${p[0]+(cl[j][0]-p[0])*close},${p[1]+(cl[j][1]-p[1])*close}`).join(' '));
 nodes.forEach((im,i)=>{let p=clamp((t-2.00)/.65);if(p<=0){im.setAttribute('opacity',0);return}let q=ease(p),ex=200+80*i,sx=128,sy=577,c1x=145+20*i,c1y=610+8*i,c2x=ex-50,c2y=684;
 let x=(1-q)**3*sx+3*(1-q)**2*q*c1x+3*(1-q)*q*q*c2x+q**3*ex,y=(1-q)**3*sy+3*(1-q)**2*q*c1y+3*(1-q)*q*q*c2y+q**3*655,size=5+33*ease(p/.8);
 im.setAttribute('x',x-size/2);im.setAttribute('y',y-size*crafts[i].ratio/2);im.setAttribute('width',size);im.setAttribute('height',size*crafts[i].ratio);im.setAttribute('opacity',ease(p/.16));});
 let title=ease((t-1.00)/.45);name.setAttribute('opacity',title);name.setAttribute('x',215+12*(1-title));name.setAttribute('y',560-parseFloat(name.getAttribute('height'))/2);
 document.getElementById('copy').setAttribute('opacity',ease((t-2.65)/.45));
}
function tick(now){let t=(now-start)/1000;render(t);if(t<4.2)request=requestAnimationFrame(tick);else{render(4.2);window.dispatchEvent(new CustomEvent('artist-house-splash-complete'));}}
function play(){cancelAnimationFrame(request);if(matchMedia('(prefers-reduced-motion: reduce)').matches){render(4.2);setTimeout(complete,250);return;}start=performance.now();request=requestAnimationFrame(tick);}
// For app handoff: listen for `artist-house-splash-complete` to navigate to Home.
window.ArtistHouseSplash={play,seek:t=>{cancelAnimationFrame(request);render(t)},duration:4.2};document.getElementById('replay').addEventListener('click',play);
Promise.all(crafts.map(a=>new Promise(resolve=>{let im=new Image;im.onload=resolve;im.onerror=resolve;im.src=a.src}))).then(play);
